import{_ as a,o as e,c as r,O as d}from"./chunks/framework.57749cb7.js";const p=JSON.parse('{"title":"学习路线","description":"四条可执行的学习路线：前端、Java 后端、全栈、AI 应用。每周读哪几篇、练什么，都标好了。","frontmatter":{"description":"四条可执行的学习路线：前端、Java 后端、全栈、AI 应用。每周读哪几篇、练什么，都标好了。","tags":["roadmap.md","并发编程","容器与运维","大模型"]},"headers":[],"relativePath":"roadmap.md","filePath":"roadmap.md","lastUpdated":1793245104000}'),o={name:"roadmap.md"};function n(h,t,s,l,c,i){return e(),r("div",null,t[0]||(t[0]=[d(`<h1 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h1><blockquote><p>站里有 300 多篇笔记，但<strong>按什么顺序读</strong>没人告诉你。这一页就是那个顺序。 四条路线，每条都标了「第几周读哪几篇、练什么」。链接直接点，读完打勾。</p></blockquote><h2 id="路线怎么选" tabindex="-1">路线怎么选 <a class="header-anchor" href="#路线怎么选" aria-label="Permalink to &quot;路线怎么选&quot;">​</a></h2><table><thead><tr><th>你的情况</th><th>走哪条</th><th>预计</th></tr></thead><tbody><tr><td>只会写 HTML/CSS，想找前端工作</td><td><a href="#路线一前端从零到能干活">路线一：前端</a></td><td>12 周</td></tr><tr><td>前端想转后端 / 后端补基础</td><td><a href="#路线二java-后端">路线二：Java 后端</a></td><td>8 周</td></tr><tr><td>想一个人把产品做出来</td><td><a href="#路线三全栈一个人把产品做出来">路线三：全栈</a></td><td>10 周</td></tr><tr><td>后端想接大模型 / 做 AI 应用</td><td><a href="#路线四ai-应用落地">路线四：AI 应用</a></td><td>6 周</td></tr></tbody></table><blockquote><p>每条路线只指向<strong>知识点笔记</strong>。刷题和面试口径自己另算 —— 学完一篇就去写代码，比连读三篇有用。</p></blockquote><hr><h2 id="路线一-前端-从零到能干活" tabindex="-1">路线一：前端，从零到能干活 <a class="header-anchor" href="#路线一-前端-从零到能干活" aria-label="Permalink to &quot;路线一：前端，从零到能干活&quot;">​</a></h2><h3 id="第-1–2-周-语言地基" tabindex="-1">第 1–2 周：语言地基 <a class="header-anchor" href="#第-1–2-周-语言地基" aria-label="Permalink to &quot;第 1–2 周：语言地基&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/frontend/html/">HTML 笔记</a></td><td>手写一个语义化、无障碍的页面骨架</td></tr><tr><td><a href="/cao_note/frontend/css/">CSS 笔记</a></td><td>用 Grid / Flex 各实现一次三栏布局</td></tr><tr><td><a href="/cao_note/frontend/Javascript/">JavaScript 笔记</a></td><td>把数组方法、闭包、原型链各写一遍</td></tr></tbody></table><p><strong>验收</strong>：不看资料写出「防抖 / 节流 / 深拷贝」，能讲清 <code>this</code> 的四种绑定。</p><h3 id="第-3–4-周-框架" tabindex="-1">第 3–4 周：框架 <a class="header-anchor" href="#第-3–4-周-框架" aria-label="Permalink to &quot;第 3–4 周：框架&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/frontend/Vue/">Vue</a>（重点：响应式原理、组合式 API）</td><td>用 Vue3 + Vite 做一个待办列表</td></tr><tr><td><a href="/cao_note/frontend/react/">React</a>（重点：Hooks、状态管理）</td><td>同样的待办用 React 再做一遍</td></tr></tbody></table><p><strong>验收</strong>：能解释「Vue 的响应式和 React 的不可变更新有什么区别」。</p><h3 id="第-5–6-周-工程化" tabindex="-1">第 5–6 周：工程化 <a class="header-anchor" href="#第-5–6-周-工程化" aria-label="Permalink to &quot;第 5–6 周：工程化&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/frontend/Vite/">Vite</a> → <a href="/cao_note/frontend/Webpack/">Webpack</a></td><td>手写一份 vite.config / webpack.config</td></tr><tr><td><a href="/cao_note/frontend/webTEA/">前端工程化</a></td><td>配 ESLint + Prettier + husky</td></tr><tr><td><a href="/cao_note/frontend/代码规范/">代码规范</a></td><td>给上面的项目加提交规范</td></tr></tbody></table><p><strong>验收</strong>：能讲清「为什么 Vite 比 Webpack 快」，能独立配一个新项目。</p><h3 id="第-7–8-周-typescript" tabindex="-1">第 7–8 周：TypeScript <a class="header-anchor" href="#第-7–8-周-typescript" aria-label="Permalink to &quot;第 7–8 周：TypeScript&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/frontend/Typescript/">TypeScript</a></td><td>把前面的待办项目改成 TS，不许用 <code>any</code></td></tr></tbody></table><p><strong>验收</strong>：能写泛型约束、能理解 <code>type</code> 与 <code>interface</code> 的取舍。</p><h3 id="第-9–10-周-性能与深度" tabindex="-1">第 9–10 周：性能与深度 <a class="header-anchor" href="#第-9–10-周-性能与深度" aria-label="Permalink to &quot;第 9–10 周：性能与深度&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/frontend/性能优化/">性能优化</a></td><td>用 Lighthouse 给自己的项目打分并优化到 90+</td></tr><tr><td><a href="/cao_note/frontend/浏览器技巧">浏览器技巧</a></td><td>会用 DevTools 看渲染、看内存</td></tr><tr><td><a href="/cao_note/frontend/设计模式/">设计模式（前端）</a></td><td>把项目里重复的 if-else 抽成策略表</td></tr></tbody></table><h3 id="第-11–12-周-收尾" tabindex="-1">第 11–12 周：收尾 <a class="header-anchor" href="#第-11–12-周-收尾" aria-label="Permalink to &quot;第 11–12 周：收尾&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/frontend/测试/">测试</a></td><td>给核心工具函数补单测</td></tr><tr><td><a href="/cao_note/frontend/小程序/">小程序</a> 或 <a href="/cao_note/frontend/React-Native/">React Native</a></td><td>选一个做个小东西</td></tr></tbody></table><p><strong>验收</strong>：有一个能跑、有测试、能部署的前端项目。</p><hr><h2 id="路线二-java-后端" tabindex="-1">路线二：Java 后端 <a class="header-anchor" href="#路线二-java-后端" aria-label="Permalink to &quot;路线二：Java 后端&quot;">​</a></h2><h3 id="第-1–2-周-语言" tabindex="-1">第 1–2 周：语言 <a class="header-anchor" href="#第-1–2-周-语言" aria-label="Permalink to &quot;第 1–2 周：语言&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/Java/01-java基础">01 Java 基础</a></td><td>把集合、异常、泛型各写一遍</td></tr><tr><td><a href="/cao_note/backend/Java/02-java核心特性">02 Java 核心特性</a></td><td>手写一个 HashMap</td></tr><tr><td><a href="/cao_note/backend/Java/03-java高级特性">03 Java 高级特性</a></td><td>Stream 改写 10 段 for 循环</td></tr></tbody></table><h3 id="第-3-周-并发-最重要的一周" tabindex="-1">第 3 周：并发（最重要的一周） <a class="header-anchor" href="#第-3-周-并发-最重要的一周" aria-label="Permalink to &quot;第 3 周：并发（最重要的一周）&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/Java/06-JUC并发编程">06 JUC 并发编程</a></td><td>手写生产者消费者、线程池、LRU</td></tr><tr><td><a href="/cao_note/backend/Java/07-Java网络编程与NIO">07 网络编程与 NIO</a></td><td>用 Selector 写个 echo 服务</td></tr></tbody></table><p><strong>验收</strong>：能讲清 AQS、锁升级、线程池七参数，能手写一个不崩的线程池。</p><h3 id="第-4-周-运行时" tabindex="-1">第 4 周：运行时 <a class="header-anchor" href="#第-4-周-运行时" aria-label="Permalink to &quot;第 4 周：运行时&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/Java/JVM深入">JVM 深入</a></td><td>用 jmap / jstack / Arthas 各排查一次问题</td></tr><tr><td><a href="/cao_note/backend/Java/08-JDK新特性与升级实践">08 JDK 新特性</a></td><td>把一个项目从 8 升到 17</td></tr></tbody></table><h3 id="第-5–6-周-框架" tabindex="-1">第 5–6 周：框架 <a class="header-anchor" href="#第-5–6-周-框架" aria-label="Permalink to &quot;第 5–6 周：框架&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/Java/04-java框架技术栈">04 框架技术栈</a>（Spring / Boot / Security / <strong>Spring AI</strong>）</td><td>搭一个带鉴权的 CRUD</td></tr><tr><td><a href="/cao_note/backend/Java/MyBatis-Plus">MyBatis-Plus</a></td><td>分页、乐观锁、逻辑删除各用一次</td></tr></tbody></table><h3 id="第-7-周-中间件" tabindex="-1">第 7 周：中间件 <a class="header-anchor" href="#第-7-周-中间件" aria-label="Permalink to &quot;第 7 周：中间件&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/Java/消息队列">消息队列</a> → <a href="/cao_note/backend/Java/Kafka深入">Kafka 深入</a></td><td>做一次「下单 → 异步扣库存」</td></tr><tr><td><a href="/cao_note/backend/Java/定时任务调度">定时任务调度</a></td><td>用 XXL-Job 跑一个分片任务</td></tr></tbody></table><h3 id="第-8-周-分布式与运维" tabindex="-1">第 8 周：分布式与运维 <a class="header-anchor" href="#第-8-周-分布式与运维" aria-label="Permalink to &quot;第 8 周：分布式与运维&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/Java/SpringCloud微服务">Spring Cloud 微服务</a></td><td>搭 Nacos + Gateway + Feign 三件套</td></tr><tr><td><a href="/cao_note/backend/Java/Arthas">Arthas</a> + <a href="/cao_note/backend/Java/CICD">CI/CD</a></td><td>把项目做成一条流水线</td></tr></tbody></table><blockquote><p>数据库单独走：<a href="/cao_note/database/MySQL深入">MySQL 深入</a> → <a href="/cao_note/database/Redis">Redis</a> → <a href="/cao_note/database/分库分表">分库分表</a>。 建议穿插在第 5–7 周，别堆到最后。</p></blockquote><hr><h2 id="路线三-全栈-一个人把产品做出来" tabindex="-1">路线三：全栈，一个人把产品做出来 <a class="header-anchor" href="#路线三-全栈-一个人把产品做出来" aria-label="Permalink to &quot;路线三：全栈，一个人把产品做出来&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code-dark"><code><span class="line"><span style="color:#e1e4e8;">周 1–4   前端基础（路线一的第 1–4 周）</span></span>
<span class="line"><span style="color:#e1e4e8;">周 5–8   Java 语言 + 并发 + 框架（路线二的第 1–6 周，可压缩）</span></span>
<span class="line"><span style="color:#e1e4e8;">周 9     数据库：MySQL 深入 + Redis</span></span>
<span class="line"><span style="color:#e1e4e8;">周 10    部署：Linux + Docker + Nginx</span></span>
<span class="line"><span style="color:#e1e4e8;">─────────── 然后做一个真项目 ───────────</span></span></code></pre><pre class="shiki github-light vp-code-light"><code><span class="line"><span style="color:#24292e;">周 1–4   前端基础（路线一的第 1–4 周）</span></span>
<span class="line"><span style="color:#24292e;">周 5–8   Java 语言 + 并发 + 框架（路线二的第 1–6 周，可压缩）</span></span>
<span class="line"><span style="color:#24292e;">周 9     数据库：MySQL 深入 + Redis</span></span>
<span class="line"><span style="color:#24292e;">周 10    部署：Linux + Docker + Nginx</span></span>
<span class="line"><span style="color:#24292e;">─────────── 然后做一个真项目 ───────────</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>关键不是「都学一遍」，而是<strong>第 11 周开始做一个有登录、有数据库、有部署的项目</strong>。参考这条真实的落地过程：</p><ul><li><a href="/cao_note/backend/Java/项目复盘-心理健康AI助手">项目复盘：心理健康 AI 助手</a> —— 从表结构、SSE 流式到部署踩坑的完整链路</li></ul><p>部署部分的最低要求：</p><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/devops/Linux">Linux</a></td><td>会用 <code>top</code> / <code>df</code> / <code>netstat</code> 定位问题</td></tr><tr><td><a href="/cao_note/devops/Docker">Docker</a></td><td>把项目打成镜像跑起来</td></tr><tr><td><a href="/cao_note/devops/Nginx">Nginx</a></td><td>配一次反向代理 + HTTPS</td></tr><tr><td><a href="/cao_note/devops/Kubernetes">Kubernetes</a></td><td>可选，知道 Pod / Service 是什么即可</td></tr></tbody></table><hr><h2 id="路线四-ai-应用落地" tabindex="-1">路线四：AI 应用落地 <a class="header-anchor" href="#路线四-ai-应用落地" aria-label="Permalink to &quot;路线四：AI 应用落地&quot;">​</a></h2><blockquote><p>前提：会写一门后端语言（Java 或 Python），有 Web 服务的基本功。</p></blockquote><h3 id="第-1-周-搞清楚模型能干什么" tabindex="-1">第 1 周：搞清楚模型能干什么 <a class="header-anchor" href="#第-1-周-搞清楚模型能干什么" aria-label="Permalink to &quot;第 1 周：搞清楚模型能干什么&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/AI-Agent/01-大模型基础">01 大模型基础</a></td><td>算清一次对话的 token 成本</td></tr><tr><td><a href="/cao_note/backend/AI-Agent/02-Prompt工程">02 Prompt 工程</a></td><td>写一个带 JSON 输出约束的 Prompt</td></tr></tbody></table><h3 id="第-2–3-周-rag-最实用的一块" tabindex="-1">第 2–3 周：RAG（最实用的一块） <a class="header-anchor" href="#第-2–3-周-rag-最实用的一块" aria-label="Permalink to &quot;第 2–3 周：RAG（最实用的一块）&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/AI-Agent/03-RAG体系">03 RAG 体系</a></td><td>用 50 篇文档搭一条可量化的检索链路</td></tr><tr><td><a href="/cao_note/database/Elasticsearch">Elasticsearch</a></td><td>用 ES 的 kNN 做混合检索</td></tr></tbody></table><p><strong>验收</strong>：有一份 20 条问题的评估集，能说出 Recall@5 是多少。</p><h3 id="第-4-周-工具调用" tabindex="-1">第 4 周：工具调用 <a class="header-anchor" href="#第-4-周-工具调用" aria-label="Permalink to &quot;第 4 周：工具调用&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/AI-Agent/04-工具调用与MCP">04 工具调用与 MCP</a></td><td>让模型查一次真实数据库（带参数校验）</td></tr></tbody></table><h3 id="第-5-周-agent" tabindex="-1">第 5 周：Agent <a class="header-anchor" href="#第-5-周-agent" aria-label="Permalink to &quot;第 5 周：Agent&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/AI-Agent/05-Agent编排">05 Agent 编排</a></td><td>一个最多 5 步、带刹车的 ReAct Agent</td></tr><tr><td><a href="/cao_note/backend/AI-Agent/06-记忆与多智能体">06 记忆与多智能体</a></td><td>给对话加上摘要压缩</td></tr></tbody></table><h3 id="第-6-周-能上线" tabindex="-1">第 6 周：能上线 <a class="header-anchor" href="#第-6-周-能上线" aria-label="Permalink to &quot;第 6 周：能上线&quot;">​</a></h3><table><thead><tr><th>读什么</th><th>练什么</th></tr></thead><tbody><tr><td><a href="/cao_note/backend/AI-Agent/07-工程化落地">07 工程化落地</a></td><td>加超时、熔断、用量统计</td></tr><tr><td><a href="/cao_note/backend/Java/04-java框架技术栈">04 框架技术栈 · 第 8 章 Spring AI</a></td><td>用 Spring AI 重写上面的链路</td></tr><tr><td><a href="/cao_note/devops/OpenTelemetry可观测性">OpenTelemetry 可观测性</a></td><td>把 token 与延迟打到自己面板上</td></tr></tbody></table><p><strong>验收</strong>：能讲清「为什么后端接模型而不是前端直连」，以及成本怎么控。</p><hr><h2 id="用法建议" tabindex="-1">用法建议 <a class="header-anchor" href="#用法建议" aria-label="Permalink to &quot;用法建议&quot;">​</a></h2><ol><li><strong>别按周死磕</strong>：一周的量按自己节奏拆，但别跳着读（后面的文章默认你懂前面的）。</li><li><strong>每篇读完整一段代码</strong>：站里的示例都是能跑的最小片段，抄一遍比读三遍管用。</li><li><strong>读不下去就换</strong>：卡住超过 20 分钟，先去做练习，回头再看。</li><li><strong>做完一个项目再回来补</strong>：很多概念是「用过了才看懂」。</li></ol>`,65)]))}const f=a(o,[["render",n]]);export{p as __pageData,f as default};
